import re
import unicodedata
import hashlib


# Exact normalized title anchors, with duration bands for short generic-looking titles.
def exact_title_anchor(r):
    def norm(s):
        s = unicodedata.normalize("NFKD", str(s or "")).encode("ascii", "ignore").decode()
        s = s.casefold().replace("&", " and ")
        return " ".join(re.findall(r"[a-z0-9]+", s))

    def key(prefix, value):
        return prefix + hashlib.blake2s(value.encode(), digest_size=8).hexdigest()

    raw = r.get("title", "")
    title = norm(raw)
    if not title:
        return []
    stripped = norm(re.sub(r"[\(\[\{].*?[\)\]\}]", " ", str(raw)))
    forms = list(dict.fromkeys(x for x in (title, stripped) if x))
    try:
        duration = float(r.get("duration", ""))
    except (TypeError, ValueError):
        duration = None

    out = []
    for form in forms[:2]:
        if len(form) >= 12 or len(form.split()) >= 3 or duration is None:
            out.append(key("t:", form))
        if duration is not None:
            band = int(duration // 120)
            out.extend(key("td:", form + "|" + str(b)) for b in (band, band - 1))
    return list(dict.fromkeys(out))


# Normalized release-plus-artist keys tolerate articles, featured performers, and accompaniment suffixes.
def release_artist_anchor(r):
    def norm(s):
        s = unicodedata.normalize("NFKD", str(s or "")).encode("ascii", "ignore").decode()
        s = s.casefold().replace("&", " and ")
        return " ".join(re.findall(r"[a-z0-9]+", s))

    def artist_forms(s):
        full = norm(s)
        if not full:
            return []
        base = re.split(
            r"\b(?:featuring|feat|ft|with)\b|[;/_]|\band\b",
            full,
            maxsplit=1,
        )[0].strip()
        base = re.sub(r"^(?:the|a|an)\s+", "", base)
        base = re.sub(
            r"\s+(?:his|her|their)\s+(?:orchestra|band|ensemble|group|combo)$",
            "",
            base,
        )
        full_no_article = re.sub(r"^(?:the|a|an)\s+", "", full)
        return list(dict.fromkeys(x for x in (full, full_no_article, base) if x))

    def key(value):
        return "ra:" + hashlib.blake2s(value.encode(), digest_size=8).hexdigest()

    release = norm(r.get("release", ""))
    if not release:
        return []
    return [key(release + "|" + artist) for artist in artist_forms(r.get("artist_name", ""))[:3]]


# Artist identity combined with overlapping wide duration bands catches mislabeled tracks without giant artist blocks.
def artist_duration_anchor(r):
    def norm(s):
        s = unicodedata.normalize("NFKD", str(s or "")).encode("ascii", "ignore").decode()
        s = s.casefold().replace("&", " and ")
        return " ".join(re.findall(r"[a-z0-9]+", s))

    def forms(s):
        full = norm(s)
        if not full:
            return []
        no_article = re.sub(r"^(?:the|a|an)\s+", "", full)
        base = re.split(
            r"\b(?:featuring|feat|ft|with)\b|[;/_]|\band\b",
            no_article,
            maxsplit=1,
        )[0].strip()
        base = re.sub(
            r"\s+(?:his|her|their)?\s*(?:orchestra|band|ensemble|group|combo)$",
            "",
            base,
        ).strip()
        return list(dict.fromkeys(x for x in (full, no_article, base) if x))

    def key(value):
        return "ad:" + hashlib.blake2s(value.encode(), digest_size=8).hexdigest()

    artists = forms(r.get("artist_name", ""))
    if not artists:
        return []
    try:
        duration = float(r.get("duration", ""))
    except (TypeError, ValueError):
        release = norm(r.get("release", ""))
        return [key(a + "|r|" + release) for a in artists[:2] if release]

    band = int(duration // 120)
    return list(dict.fromkeys(
        key(a + "|" + str(b))
        for a in artists[:2]
        for b in (band, band - 1)
    ))


# Informative token and consonant signatures handle spelling errors, reordered text, and near-phonetic artist aliases.
def fuzzy_token_signature(r):
    def norm(s):
        s = unicodedata.normalize("NFKD", str(s or "")).encode("ascii", "ignore").decode()
        s = s.casefold().replace("&", " and ")
        return " ".join(re.findall(r"[a-z0-9]+", s))

    def phonetic(s):
        s = norm(s)
        s = re.sub(r"^(?:the|a|an)\s+", "", s)
        s = re.split(r"\b(?:featuring|feat|ft|with)\b|[;/_]|\band\b", s, maxsplit=1)[0]
        s = s.translate(str.maketrans({"c": "k", "q": "k", "d": "t", "g": "k",
                                      "b": "p", "v": "f", "z": "s", "x": "s"}))
        words = []
        for word in s.split():
            sig = word[:1] + re.sub(r"[aeiouyhw]", "", word[1:])
            sig = re.sub(r"(.)\1+", r"\1", sig)
            if sig:
                words.append(sig)
        return " ".join(words)

    def key(prefix, value):
        return prefix + hashlib.blake2s(value.encode(), digest_size=8).hexdigest()

    stop = {
        "the", "and", "for", "from", "this", "that", "with", "into", "version",
        "album", "original", "digital", "remaster", "remastered", "live", "edit",
        "mix", "feat", "featuring", "vol", "volume",
    }
    text = norm(r.get("title", "") + " " + r.get("release", ""))
    tokens = {t for t in text.split() if len(t) >= 3 and t not in stop}
    tokens = sorted(tokens, key=lambda t: (-len(t), t))[:3]
    try:
        duration = float(r.get("duration", ""))
    except (TypeError, ValueError):
        duration = None

    out = []
    if duration is not None:
        band = int(duration // 150)
        for token in tokens:
            out.extend(key("fd:", token + "|" + str(b)) for b in (band, band - 1))
        artist_sig = phonetic(r.get("artist_name", ""))
        if artist_sig:
            out.extend(key("fp:", artist_sig + "|" + str(b)) for b in (band, band - 1))
    else:
        release = norm(r.get("release", ""))
        for token in tokens:
            out.append(key("fr:", token + "|" + release))
    return list(dict.fromkeys(out))


SCHEMES = {
    "exact_title_anchor": exact_title_anchor,
    "release_artist_anchor": release_artist_anchor,
    "artist_duration_anchor": artist_duration_anchor,
    "fuzzy_token_signature": fuzzy_token_signature,
}
